31	static bool get_current_so_dir(char *dir_buf, size_t buf_len)
32	{
33	    if (dir_buf == nullptr || buf_len == 0) {
34	        return false;
35	    }
36	
37	    Dl_info info;
38	    if (dladdr((void *)&get_current_so_dir, &info) == 0 || info.dli_fname == nullptr) {
39	        return false;
40	    }
41	
42	    const char *so_path = info.dli_fname;
43	    const char *slash = strrchr(so_path, '/');
44	    if (slash == nullptr) {
45	        return false;
46	    }
47	
48	    size_t dir_len = static_cast<size_t>(slash - so_path);
49	    if (dir_len + 1 > buf_len) {
50	        return false;
51	    }
52	
53	    memcpy(dir_buf, so_path, dir_len);
54	    dir_buf[dir_len] = '\0';
55	    return true;
56	}
57	
58	static void *safe_dlopen(const char *so_name)
59	{
60	    if (so_name == nullptr || so_name[0] == '\0') {
61	        SHM_LOG_ERROR("Failed to load SO: invalid so_name");
62	        return nullptr;
63	    }
64	
65	    char so_dir[PATH_MAX] = {0};
66	    if (get_current_so_dir(so_dir, sizeof(so_dir))) {
67	        char full_path[PATH_MAX] = {0};
68	        int ret = snprintf(full_path, sizeof(full_path), "%s/%s", so_dir, so_name);
69	        if (ret > 0 && static_cast<size_t>(ret) < sizeof(full_path)) {
70	            dlerror();
71	            void *handle_by_full_path = dlopen(full_path, RTLD_NOW);
72	            if (handle_by_full_path != nullptr) {
73	                return handle_by_full_path;
74	            }
75	        }
76	    }
77	
78	    dlerror();
79	    void *handle = dlopen(so_name, RTLD_NOW);
80	    const char *err = dlerror();
81	    if (!handle) {
82	        SHM_LOG_ERROR("Failed to load SO: " << so_name << ", dlerror: " << (err ? err : "unknown error"));
83	    }
84	    return handle;
85	}
86	
87	static void safe_dlclose(void **handle)
88	{
89	    if (handle && *handle) {
90	        dlclose(*handle);
91	        *handle = nullptr;
92	    }
93	}
