121	int32_t aclshmemi_bootstrap_pre_init(int flags, aclshmemi_bootstrap_handle_t *handle) {
122	    int32_t status = ACLSHMEM_SUCCESS;
123	    if (flags & ACLSHMEMX_INIT_WITH_MPI) {
124	        SHM_LOG_ERROR("Unsupported Type for bootstrap preinit.");
125	        return ACLSHMEM_INVALID_PARAM;
126	    } else if (flags & ACLSHMEMX_INIT_WITH_UNIQUEID) {
127	        plugin_name = BOOTSTRAP_MODULE_CONFIG_STORE;
128	    } else if (flags & ACLSHMEMX_INIT_WITH_DEFAULT) {
129	        plugin_name = BOOTSTRAP_MODULE_CONFIG_STORE;
130	    } else {
131	        SHM_LOG_ERROR("Unknown Type for bootstrap");
132	        status = ACLSHMEM_INVALID_PARAM;
133	    }
134	    aclshmemi_bootstrap_loader();
135	    if (!plugin_hdl) {
136	        SHM_LOG_ERROR("Bootstrap unable to load " << plugin_name
137	            << ", please ensure the SO file is in the same directory as aclshmem.so.");
138	        aclshmemi_bootstrap_free();
139	        return ACLSHMEM_INVALID_VALUE;
140	    }
141	    int (*plugin_pre_init)(aclshmemi_bootstrap_handle_t *);
142	    dlerror();
143	    *((void **)&plugin_pre_init) = dlsym(plugin_hdl, BOOTSTRAP_PLUGIN_PREINIT_FUNC);
144	    const char *dlsym_err = dlerror();
145	    if (!plugin_pre_init || dlsym_err) {
146	        SHM_LOG_ERROR("Bootstrap plugin pre_init func dlsym failed: " << (dlsym_err ? dlsym_err : "unknown error"));
147	        aclshmemi_bootstrap_free();
148	        return ACLSHMEM_INNER_ERROR;
149	    }
150	    status = plugin_pre_init(&g_boot_handle);
151	    if (status != 0) {
152	        SHM_LOG_ERROR("Bootstrap plugin init failed for " << plugin_name);
153	        aclshmemi_bootstrap_free();
154	        return ACLSHMEM_INNER_ERROR;
155	    }
156	    return status;
157	}
