159	void remove_tcp_prefix_and_copy(const char* input, char* output, size_t output_len) {
160	    memset(output, 0, output_len);
161	    if (output_len == 0) return;
162	
163	    if (input == nullptr || strlen(input) == 0) {
164	        return;
165	    }
166	
167	    const char* prefix_tcp = "tcp://";
168	    const char* prefix_tcp6 = "tcp6://";
169	    size_t len_tcp = strlen(prefix_tcp);
170	    size_t len_tcp6 = strlen(prefix_tcp6);
171	    const char* result_ptr = input;
172	
173	    if (strncmp(input, prefix_tcp, len_tcp) == 0) {
174	        result_ptr = input + len_tcp;
175	    }
176	    else if (strncmp(input, prefix_tcp6, len_tcp6) == 0) {
177	        result_ptr = input + len_tcp6;
178	    }
179	
180	    strncpy(output, result_ptr, output_len - 1);
181	    output[output_len - 1] = '\0';
182	}
183	
184	static bool is_uid_args_valid(void *arg)
185	{
186	    if (arg == nullptr) {
187	        return false;
188	    }
189	    aclshmemi_bootstrap_uid_state_t *uid_args = (aclshmemi_bootstrap_uid_state_t *)arg;
190	    struct sockaddr *sa = reinterpret_cast<struct sockaddr *>(&uid_args->addr.addr);
191	    SHM_LOG_INFO("uid_args sa_family: " << sa->sa_family);
192	    return sa->sa_family == AF_INET || sa->sa_family == AF_INET6;
193	}
