195	static bool is_valid_ip_port_url(const char *ip_port)
196	{
197	    if (ip_port == nullptr || ip_port[0] == '\0') {
198	        return false;
199	    }
200	
201	    constexpr const char *tcp_prefix = "tcp://";
202	    constexpr const char *tcp6_prefix = "tcp6://";
203	    constexpr long min_port = 1024;
204	
205	    std::string url(ip_port);
206	    std::string ip;
207	    std::string port_str;
208	
209	    if (url.rfind(tcp_prefix, 0) == 0) {
210	        std::string endpoint = url.substr(strlen(tcp_prefix));
211	        size_t colon_pos = endpoint.rfind(':');
212	        if (colon_pos == std::string::npos || colon_pos == 0 || colon_pos == endpoint.size() - 1) {
213	            return false;
214	        }
215	        ip = endpoint.substr(0, colon_pos);
216	        port_str = endpoint.substr(colon_pos + 1);
217	    } else if (url.rfind(tcp6_prefix, 0) == 0) {
218	        std::string endpoint = url.substr(strlen(tcp6_prefix));
219	        if (endpoint.size() < 4 || endpoint[0] != '[') {
220	            return false;
221	        }
222	        size_t bracket_pos = endpoint.find(']');
223	        if (bracket_pos == std::string::npos || bracket_pos + 2 >= endpoint.size() || endpoint[bracket_pos + 1] != ':') {
224	            return false;
225	        }
226	        ip = endpoint.substr(1, bracket_pos - 1);
227	        port_str = endpoint.substr(bracket_pos + 2);
228	    } else {
229	        return false;
230	    }
231	
232	    if (ip.empty() || port_str.empty()) {
233	        return false;
234	    }
235	
236	    errno = 0;
237	    char *end_ptr = nullptr;
238	    long port = std::strtol(port_str.c_str(), &end_ptr, 10);
239	    if (errno == ERANGE || end_ptr == nullptr || *end_ptr != '\0' || port <= min_port || port > UINT16_MAX) {
240	        return false;
241	    }
242	
243	    char addr_buf[sizeof(struct in6_addr)] = {0};
244	    if (inet_pton(AF_INET, ip.c_str(), addr_buf) == 1) {
245	        return true;
246	    }
247	    if (inet_pton(AF_INET6, ip.c_str(), addr_buf) == 1) {
248	        return true;
249	    }
250	    constexpr size_t maxHostnameLen = 253;
251	    if (ip.size() > maxHostnameLen) {
252	        return false;
253	    }
254	    for (char c : ip) {
255	        if (!std::isalnum(static_cast<unsigned char>(c)) && c != '-' && c != '.') {
256	            return false;
257	        }
258	    }
259	    return true;
260	}
