262	int32_t aclshmemi_bootstrap_init(int flags, aclshmemx_init_attr_t *attr) {
263	    int32_t status = ACLSHMEM_SUCCESS;
264	    void *arg;
265	    g_boot_handle.use_attr_ipport = false;
266	    // Reset session_magic to default at entry so that a non-UID init
267	    // (or a DEFAULT init after a previous UID init/finalize cycle)
268	    // never picks up a stale value from a prior session.
269	    g_boot_handle.session_magic = SHMEMI_DEFAULT_CONN_MAGIC;
270	    if (flags & ACLSHMEMX_INIT_WITH_UNIQUEID) {
271	        SHM_LOG_INFO("ACLSHMEMX_INIT_WITH_UNIQUEID");
272	        plugin_name = BOOTSTRAP_MODULE_CONFIG_STORE;
273	        arg = (attr != NULL) ? attr->comm_args : NULL;
274	        g_boot_handle.mype = attr->my_pe;
275	        g_boot_handle.npes = attr->n_pes;
276	        if (!is_uid_args_valid(arg)) {
277	            SHM_LOG_ERROR("BootStrap UID Mode Must Have UID !");
278	            return ACLSHMEM_INVALID_PARAM;
279	        }
280	    } else if (flags & ACLSHMEMX_INIT_WITH_MPI) {
281	        SHM_LOG_INFO("ACLSHMEMX_INIT_WITH_MPI");
282	        plugin_name = BOOTSTRAP_MODULE_MPI;
283	        arg = (attr != NULL) ? attr->comm_args : NULL;
284	    } else if (flags & ACLSHMEMX_INIT_WITH_DEFAULT) {
285	        SHM_LOG_INFO("ACLSHMEMX_INIT_WITH_DEFAULT");
286	        plugin_name = BOOTSTRAP_MODULE_CONFIG_STORE;
287	        arg = (attr != NULL) ? attr->comm_args : NULL;
288	        g_boot_handle.mype = attr->my_pe;
289	        g_boot_handle.npes = attr->n_pes;
290	        if (is_valid_ip_port_url(attr->ip_port)) {
291	            g_boot_handle.use_attr_ipport = true;
292	            g_boot_handle.sockFd = attr->option_attr.sockFd;
293	            g_boot_handle.timeOut = attr->option_attr.shm_init_timeout;
294	            g_boot_handle.timeControlOut = attr->option_attr.control_operation_timeout;
295	            strncpy(g_boot_handle.ipport, attr->ip_port, sizeof(g_boot_handle.ipport) - 1);
296	            g_boot_handle.ipport[sizeof(g_boot_handle.ipport) - 1] = '\0';
297	            SHM_LOG_INFO("Default bootstrap will use attr ip_port directly: " << g_boot_handle.ipport);
298	        } else if (is_uid_args_valid(arg)) {
299	            SHM_LOG_INFO("BootStrap Default Mode got invalid ip_port: "
300	                << (attr->ip_port[0] != '\0' ? attr->ip_port : "<empty>")
301	                << ", fallback to UNIQUEID bootstrap args.");
302	            g_boot_handle.use_attr_ipport = false;
303	        } else {
304	            SHM_LOG_ERROR("BootStrap Default Mode got invalid ip_port: "
305	                << (attr->ip_port[0] != '\0' ? attr->ip_port : "<empty>")
306	                << ", and no valid UNIQUEID comm_args fallback.");
307	            return ACLSHMEM_INVALID_PARAM;
308	        }
309	    } else {
310	        SHM_LOG_ERROR("Unknown Type for bootstrap");
311	        return ACLSHMEM_INVALID_PARAM;
312	    }
313	
314	    // Connection magic for init/finalize loop isolation.
315	    // If a valid UID struct is available (explicit UID mode or DEFAULT
316	    // fallback to UID args), derive session_magic from the low 16 bits of
317	    // uid_state->magic.  Otherwise session_magic stays at the default
318	    // value that was set at function entry.
319	    if ((flags & ACLSHMEMX_INIT_WITH_UNIQUEID) && arg != nullptr && is_uid_args_valid(arg)) {
320	        auto* uid_state = reinterpret_cast<aclshmemi_bootstrap_uid_state_t*>(arg);
321	        if (uid_state->magic) {
322	            g_boot_handle.session_magic = static_cast<uint16_t>(uid_state->magic);
323	        }
324	    }
325	    SHM_LOG_INFO("bootstrap session_magic=" << g_boot_handle.session_magic);
326	
327	    aclshmemi_bootstrap_loader();
328	    if (!plugin_hdl) {
329	        SHM_LOG_ERROR("Bootstrap unable to load " << plugin_name
330	            << ", please ensure the SO file is in the same directory as aclshmem.so.");
331	        aclshmemi_bootstrap_free();
332	        return ACLSHMEM_INVALID_VALUE;
333	    }
334	    int (*plugin_init)(void *, aclshmemi_bootstrap_handle_t *);
335	    dlerror();
336	    *((void **)&plugin_init) = dlsym(plugin_hdl, BOOTSTRAP_PLUGIN_INIT_FUNC);
337	    const char *dlsym_err = dlerror();
338	    if (!plugin_init || dlsym_err) {
339	        SHM_LOG_ERROR("Bootstrap plugin init func dlsym failed: " << (dlsym_err ? dlsym_err : "unknown error"));
340	        aclshmemi_bootstrap_free();
341	        return ACLSHMEM_INNER_ERROR;
342	    }
343	    SHM_LOG_INFO("Calling plugin_init for " << plugin_name
344	        << ", use_attr_ipport=" << g_boot_handle.use_attr_ipport
345	        << ", mype=" << g_boot_handle.mype
346	        << ", npes=" << g_boot_handle.npes);
347	    status = plugin_init(arg, &g_boot_handle);
348	    SHM_LOG_INFO("plugin_init returned status=" << status << " for " << plugin_name);
349	    if (status != 0) {
350	        SHM_LOG_ERROR("Bootstrap plugin init failed for " << plugin_name);
351	        aclshmemi_bootstrap_free();
352	        return ACLSHMEM_INNER_ERROR;
353	    }
354	    g_boot_handle.is_bootstraped = true;
355	    return status;
356	}
357	
358	void aclshmemi_bootstrap_finalize() {
359	    if (!g_boot_handle.is_bootstraped) {
360	        return;
361	    }
362	    g_boot_handle.finalize(&g_boot_handle);
363	    g_boot_handle.is_bootstraped = false;
364	    safe_dlclose(&plugin_hdl);
365	}

