163	static int config_store_bootstrap_allgather(const void *in, void *out, int len, aclshmemi_bootstrap_handle_t *handle) {
164	    if (!in || !out || !handle) {
165	        SHM_LOG_ERROR("bootstrap allgather: invalid arguments (nullptr).");
