174	    int nranks = handle->npes;
175	
176	    auto ret = (shm::store::SmemGroupEnginePtr(state->group_engine_))->GroupAllGather((char *)in, len, (char *)out, len * nranks);
177	    if (ret != ACLSHMEM_SUCCESS) {
