221	int32_t init_config_store(aclshmemi_bootstrap_handle_t* handle)
222	{
223	    if (!handle) {
224	        SHM_LOG_ERROR("bootstrap init_config_store: invalid arguments (nullptr).");
225	        return ACLSHMEM_BOOTSTRAP_ERROR;
226	    }
227	
228	    // Get Bootstrap state
229	    auto state = static_cast<ConfigStoreState*>(handle->bootstrap_state);
230	    if (!state) return ACLSHMEM_INNER_ERROR;
231	
232	    // Read per-session connection magic — set by the framework
233	    // in aclshmemi_bootstrap_init().
234	    uint16_t magic = handle->session_magic;
235	
236	    shm::store::StoreFactory::SetTlsInfo(false, nullptr, 0);
237	    int32_t sock_fd = handle->sockFd;
238	    shm::store::UrlExtraction option;
239	    std::string url(handle->ipport);
240	    SHM_ASSERT_RETURN(option.ExtractIpPortFromUrl(url) == ACLSHMEM_SUCCESS, ACLSHMEM_INVALID_PARAM);
241	    SHM_LOG_INFO("init_config_store: rank=" << handle->mype << "/" << handle->npes
242	        << " ipport=" << handle->ipport << " ip=" << option.ip << " port=" << option.port
243	        << " magic=" << magic << " isServer=" << (handle->mype == 0 ? "true" : "false"));
244	    if (handle->mype == 0) {
245	        state->store_ = shm::store::StoreFactory::CreateStore(option.ip, option.port, true, 0, -1, sock_fd, magic);
246	    }
247	    else {
248	        // Pass -1 to use CONNECT_RETRY_MAX_TIMES (120s total),
249	        // not handle->timeOut which is in seconds but interpreted as retry count.
250	        state->store_ = shm::store::StoreFactory::CreateStore(option.ip, option.port, false, handle->mype, -1, -1, magic);
251	    }
252	    return ACLSHMEM_SUCCESS;
253	}
