255	int32_t init_group_engine(aclshmemi_bootstrap_handle_t* handle)
256	{
257	    if (!handle) {
258	        SHM_LOG_ERROR("bootstrap init_group_engine: invalid arguments (nullptr).");
259	        return ACLSHMEM_BOOTSTRAP_ERROR;
260	    }
261	
262	    // Get Bootstrap state
263	    auto state = static_cast<ConfigStoreState*>(handle->bootstrap_state);
264	    if (!state) return ACLSHMEM_INNER_ERROR;
265	
266	    std::string prefix = "SHM_(" + std::to_string(DEFAULT_ID) + ")_";
267	    shm::store::StorePtr store_ptr = shm::store::StoreFactory::PrefixStore(state->store_, prefix);
268	    shm::store::SmemGroupOption opt = {
269	        (uint32_t)handle->npes, (uint32_t)handle->mype, handle->timeControlOut * 1000U, false, nullptr, nullptr};
270	    shm::store::SmemGroupEnginePtr group = shm::store::SmemNetGroupEngine::Create(store_ptr, opt);
271	    SHM_ASSERT_RETURN(group != nullptr, ACLSHMEM_SMEM_ERROR);
272	    state->group_engine_ = group;
273	    return ACLSHMEM_SUCCESS;
274	}
275	
276	int aclshmemi_bootstrap_plugin_init(void* comm, aclshmemi_bootstrap_handle_t* handle)
277	{
278	    std::lock_guard<std::mutex> lock(g_store_mutex);
279	    g_store_ref++;
280	
281	    int status = ACLSHMEM_SUCCESS;
282	    if (handle == nullptr) {
283	        SHM_LOG_ERROR(" aclshmemi_bootstrap_plugin_init: invalid arguments (nullptr)");
284	        return ACLSHMEM_BOOTSTRAP_ERROR;
285	    }
286	
287	    ConfigStoreState *state = new (std::nothrow) ConfigStoreState();
288	    if (state == nullptr) {
289	        SHM_LOG_ERROR("Failed to allocate memory for bootstrap state. ");
290	        return ACLSHMEM_BOOTSTRAP_ERROR;
291	    }
292	    handle->bootstrap_state = static_cast<void *>(state);
293	
294	    /* If we don't get ip_port, now get it from uid. */
295	    std::string ipPort;
296	    if (handle->use_attr_ipport == false) {
297	        aclshmemi_bootstrap_uid_state_t* uid_args = (aclshmemi_bootstrap_uid_state_t*)comm;
298	        if (uid_args->addr.type == ADDR_IPv6) {
299	            char ipStr[INET6_ADDRSTRLEN] = {0};
300	            if (inet_ntop(AF_INET6, &(uid_args->addr.addr.addr6.sin6_addr), ipStr, sizeof(ipStr)) == nullptr) {
301	                SHM_LOG_ERROR("inet_ntop failed for IPv6");
302	                return ACLSHMEM_INNER_ERROR;
303	            }
304	            uint16_t port = ntohs(uid_args->addr.addr.addr6.sin6_port);
305	            ipPort = "tcp6://[" + std::string(ipStr) + "]:" + std::to_string(port);
306	        } else {
307	            char ipStr[INET_ADDRSTRLEN] = {0};
308	            if (inet_ntop(AF_INET, &(uid_args->addr.addr.addr4.sin_addr), ipStr, sizeof(ipStr)) == nullptr) {
309	                SHM_LOG_ERROR("inet_ntop failed for IPv4");
310	                return ACLSHMEM_INNER_ERROR;
311	            }
312	            uint16_t port = ntohs(uid_args->addr.addr.addr4.sin_port);
313	            ipPort = "tcp://" + std::string(ipStr) + ":" + std::to_string(port);
314	        }
315	
316	        /* Set bootstrap Ip params. */
317	        handle->sockFd = uid_args->inner_sockFd;
318	        handle->timeOut = DEFAULT_TIMEOUT;
319	        handle->timeControlOut = DEFAULT_TIMEOUT;
320	
321	        size_t ip_len = sizeof(handle->ipport);
322	        if (ipPort.length() > ip_len) {
323	            SHM_LOG_ERROR("Generated IP String Illegal!!");
324	            return ACLSHMEM_INNER_ERROR;
325	        }
326	
327	        strncpy(handle->ipport, ipPort.c_str(), ip_len - 1);
328	        handle->ipport[ip_len - 1] = '\0';
329	        SHM_LOG_INFO("extract ip port:" << ipPort);
330	    }
331	
332	    /* Set TLS Config */
333	    status = config_store_set_tls_info(handle->tls_enable, handle->tls_info, handle->tls_info_len);
334	    if (handle->tls_enable == true) {
335	        status = config_store_bootstrap_set_tls_key(
336	                    handle->tls_pk, handle->tls_pk_len, 
337	                    handle->tls_pk_pw, handle->tls_pk_pw_len, handle->decrypt_handler);
338	    }
339	
340	    /* Init Config Store */
341	    status = init_config_store(handle);
342	    if (status != ACLSHMEM_SUCCESS) {
343	        SHM_LOG_ERROR("shmem init config store failed, error: " << status);
344	        return status;
345	    }
346	
347	    /* Init Host Communication Group Engine */
348	    status = init_group_engine(handle);
349	    if (status != ACLSHMEM_SUCCESS) {
350	        SHM_LOG_ERROR("shmem init group engine failed, error: " << status);
351	        return status;
352	    }
353	
354	    handle->allgather = config_store_bootstrap_allgather;
355	    handle->barrier = config_store_bootstrap_barrier;
356	    handle->finalize = config_store_bootstrap_finalize;
357	    handle->alltoall = nullptr;
358	    handle->global_exit = config_store_bootstrap_global_exit;
359	
360	    SHM_LOG_INFO("pe " << handle->mype << ": bootstrap plugin initialized successfully");
361	    return ACLSHMEM_SUCCESS;
362	}

