40	static inline std::pair<int32_t, int32_t> SplitSizeAndVersion(int64_t val)
41	{
42	    auto unsignedVal = static_cast<uint64_t>(val);
43	    return std::make_pair(unsignedVal >> GROUP_DYNAMIC_SIZE_BIT_LEN, unsignedVal & GROUP_DYNAMIC_SIZE_BIT_MASK);
44	}
