47	{
48	    auto unsignedVer = static_cast<uint32_t>(ver);
49	    auto unsignedSize = static_cast<uint32_t>(size);
50	    return ((1LL * unsignedVer) << GROUP_DYNAMIC_SIZE_BIT_LEN) | unsignedSize;
51	}
