80	Result SmemNetGroupEngine::GroupBarrier()
81	{
82	    SHM_ASSERT_RETURN(store_ != nullptr, SM_INVALID_PARAM);
83	    uint32_t size = option_.rankSize;
84	    std::string idx = std::to_string(groupVersion_) + "_" + std::to_string(++barrierGroupSn_);
85	    std::string addKey = idx + "_BA";
86	    std::string waitKey = idx + "_BW";
87	    int64_t val = 0;
88	
89	    MonoPerfTrace traceBarrier;
90	    /* all guys add 1 to barrier key and get it */
91	    MonoPerfTrace traceAdd;
92	    auto ret = store_->Add(addKey, 1, val);
93	    SHM_VALIDATE_RETURN(ret == SM_OK, "store add key: " << store_->GetCompleteKey(addKey)
94	                        << " failed, result:" << ConfigStore::ErrStr(ret), SM_ERROR);
95	
96	    traceAdd.RecordEnd();
97	    SHM_LOG_DEBUG("store add key: " << store_->GetCompleteKey(addKey) << " value: " << val);
98	
99	    /* only the first rank needs to clear the last key, and it's unnecessary to clear map for first time */
100	    if (val == 1 && barrierGroupSn_ > REMOVE_INTERVAL) {
101	        uint32_t removeBarrierGroupSn_ = barrierGroupSn_ - REMOVE_INTERVAL;
102	        std::string removeAddIdx = std::to_string(groupVersion_) + "_" + std::to_string(removeBarrierGroupSn_) + "_BA";
103	        std::string removeWaitIdx = std::to_string(groupVersion_) + "_" + std::to_string(removeBarrierGroupSn_) + "_BW";
104	        /* There is no need to return ERROR, when the removed key is already not exist.
105	        The WARNING LOG is contained in the remove func itself, no need to print more log. */
106	        (void)store_->Remove(removeAddIdx);
107	        (void)store_->Remove(removeWaitIdx);
108	    }
109	
110	    /* the last guy set the status to ok, and other guys just wait for the last guy set the value */
111	    if (val == size) {
112	        ret = store_->Set(waitKey, SMEM_GROUP_SET_STR);
113	        SHM_VALIDATE_RETURN(ret == SM_OK, "store set key: " << store_->GetCompleteKey(waitKey)
114	                     << " failed, result:" << ConfigStore::ErrStr(ret), SM_ERROR);
115	        SHM_LOG_DEBUG("store set key: " << store_->GetCompleteKey(waitKey));
116	    }
117	
118	    /* all guys wait for waitKey status with timeout, timeout happens if the ok status not set by the last guy */
119	    MonoPerfTrace traceGetStatus;
120	    std::string getVal;
121	    ret = store_->Get(waitKey, getVal, option_.timeoutMs);
122	    SHM_VALIDATE_RETURN(ret == SM_OK, "store get key: " << store_->GetCompleteKey(waitKey)
123	                     << " failed, result:" << ConfigStore::ErrStr(ret), SM_ERROR);
124	    traceGetStatus.RecordEnd();
125	
126	    SHM_VALIDATE_RETURN(getVal == SMEM_GROUP_SET_STR, "store get key: " << store_->GetCompleteKey(waitKey) <<
127	                     " val is not equal, val: " << getVal << " expect: " << SMEM_GROUP_SET_STR, SM_ERROR);
128	    traceBarrier.RecordEnd();
129	
130	    SHM_LOG_INFO("groupBarrier successfully, key: " << store_->GetCompleteKey(waitKey) << ", size: " <<
131	        size << ", timeCostUs: total(" << traceBarrier.PeriodUs() << ") add(" << traceAdd.PeriodUs() <<
132	        ") getStatus(" << traceGetStatus.PeriodUs() << ")");
133	    return SM_OK;
134	}
