136	static inline void GatherFillRank(std::vector<uint8_t> &vec, uint32_t rank)
137	{
138	    uint32_t *st = reinterpret_cast<uint32_t *>(vec.data());
139	    *st = rank;
140	}
141	
142	static void SortGatherRecv(std::vector<uint8_t> &vec, uint32_t preSize, uint32_t rankSize, char *recvBuf)
143	{
144	    std::vector<std::pair<uint32_t, uint32_t>> offset(rankSize);
145	    uint32_t unitSize = preSize + SMEM_GATHER_PREFIX_SIZE;
146	    uint8_t *ptr = vec.data();
147	    for (uint32_t i = 0; i < rankSize; i++) {
148	        uint32_t idx = i * unitSize;
149	        std::copy_n(reinterpret_cast<uint32_t *>(ptr + idx), 1, &offset[i].first);
150	        offset[i].second = idx + SMEM_GATHER_PREFIX_SIZE;
151	    }
152	
153	    std::sort(offset.begin(), offset.end());
154	    for (uint32_t i = 0; i < rankSize; i++) {
155	        (void)std::copy_n(ptr + offset[i].second, preSize, recvBuf + preSize * i);
156	    }
157	}
