170	Result SmemNetGroupEngine::RegisterExit(const std::function<void(int)> &exit)
171	{
172	    if (globalExitHandler_ != nullptr) {
173	        SHM_LOG_INFO("the exit function is not null");
174	        return SM_INVALID_PARAM;
175	    }
176	    SHM_ASSERT_RETURN(exit != nullptr, SM_INVALID_PARAM);
177	    SHM_ASSERT_RETURN(store_ != nullptr, SM_INVALID_PARAM);
178	    globalExitHandler_ = exit;
179	    uint32_t wid;
180	    auto ret = store_->Watch(SMEM_GROUP_EXIT_KEY, std::bind(&SmemNetGroupEngine::RankExit, this,
181	                                                            std::placeholders::_1, std::placeholders::_2,
182	                                                            std::placeholders::_3), wid);
183	    if (ret != SM_OK) {
184	        SHM_LOG_INFO("group watch failed, maybe link down, ret: " << ret);
185	        globalExitHandler_ = nullptr;
186	        return ret;
187	    }
188	    return SM_OK;
189	}
190	
191	void SmemNetGroupEngine::RankExit(int result, const std::string &key, const std::string &value)
192	{
193	    if (result == SUCCESS && globalExitHandler_ != nullptr) {
194	        int val = 0;
195	        try {
196	            val = std::stoi(value);
197	        } catch (...) {
198	            SHM_LOG_INFO("convert string to int failed:" << value);
199	            return;
200	        }
201	        globalExitHandler_(val);
202	    } else {
203	        SHM_LOG_INFO("global exit failed:" << value);
204	    }
205	}
206	
207	Result SmemNetGroupEngine::GroupAllGather(const char *sendBuf, uint32_t sendSize, char *recvBuf, uint32_t recvSize)
208	{
209	    SHM_ASSERT_RETURN(store_ != nullptr, SM_INVALID_PARAM);
210	    uint32_t size = option_.rankSize;
211	    SHM_ASSERT_RETURN(sendSize * size == recvSize, SM_INVALID_PARAM);
212	
213	    std::string idx = std::to_string(groupVersion_) + "_" + std::to_string(++allGatherGroupSn_);
214	    std::string addKey = idx + "_GA";
215	    std::string waitKey = idx + "_GW";
216	
217	    std::vector<uint8_t> input(sendSize + SMEM_GATHER_PREFIX_SIZE);
218	    GatherFillRank(input, option_.rank);
219	    (void)std::copy_n(sendBuf, sendSize, input.data() + SMEM_GATHER_PREFIX_SIZE);
220	
221	    MonoPerfTrace traceAllGather;
222	    /* append things and get the length of value */
223	    MonoPerfTrace traceAppend;
224	    uint64_t val = 0;
225	    auto ret = store_->Append(addKey, input, val);
226	    SHM_VALIDATE_RETURN(ret == SM_OK, "store add key: " << store_->GetCompleteKey(addKey)
227	                       << " failed, result:" << ConfigStore::ErrStr(ret), SM_ERROR);
228	    traceAppend.RecordEnd();
229	
230	    /* only the first rank needs to clear the last key, and it's unnecessary to clear map for first time */
231	    if (val == input.size() && allGatherGroupSn_ > REMOVE_INTERVAL) {
232	        uint32_t rmAllGatherGroupSn_ = allGatherGroupSn_- REMOVE_INTERVAL;
233	        std::string removeAddIdx = std::to_string(groupVersion_) + "_" + std::to_string(rmAllGatherGroupSn_) + "_GA";
234	        std::string removeWaitIdx = std::to_string(groupVersion_) + "_" + std::to_string(rmAllGatherGroupSn_) + "_GW";
235	        /* There is no need to return ERROR, when the removed key is already not exist.
236	        The WARNING LOG is contained in the remove func itself, no need to print more log. */
237	        (void)store_->Remove(removeAddIdx);
238	        (void)store_->Remove(removeWaitIdx);
239	    }
240	    /* the last guy set ok status */
241	    if (val == input.size() * size) {
242	        ret = store_->Set(waitKey, SMEM_GROUP_SET_STR);
243	        SHM_VALIDATE_RETURN(ret == SM_OK, "store set key: " << store_->GetCompleteKey(waitKey)
244	                         << " failed, result:" << ConfigStore::ErrStr(ret), SM_ERROR);
245	    }
246	
247	    /* all guys wait for ok status with timeout */
248	    MonoPerfTrace traceGetStatus;
249	    std::string getVal;
250	    ret = store_->Get(waitKey, getVal, option_.timeoutMs);
251	    SHM_VALIDATE_RETURN(ret == SM_OK, "store get key: " << store_->GetCompleteKey(waitKey)
252	                << " failed, result:" << ConfigStore::ErrStr(ret), SM_ERROR);
253	    traceGetStatus.RecordEnd();
254	
255	    SHM_VALIDATE_RETURN(getVal == SMEM_GROUP_SET_STR, "store get key: " << store_->GetCompleteKey(waitKey)
256	                     << " val is not equal, val: " << getVal << " expect: " << SMEM_GROUP_SET_STR, SM_ERROR);
257	
258	    /* get the whole value */
259	    MonoPerfTrace traceGetData;
260	    std::vector<uint8_t> output;
261	    ret = store_->Get(addKey, output, option_.timeoutMs);
262	    if (ret != SM_OK || output.size() != input.size() * size) {
263	        SHM_LOG_ERROR("after wait, store get key: " << store_->GetCompleteKey(addKey)
264	                      << " failed, result:" << ConfigStore::ErrStr(ret)
265	                      << " recv_size: " << output.size() << " input_size:" << input.size()
266	                      << " group_size:" << size);
267	        return SM_ERROR;
268	    }
269	    traceGetData.RecordEnd();
270	    traceAllGather.RecordEnd();
271	
272	    SortGatherRecv(output, sendSize, size, recvBuf);
273	
274	    SHM_LOG_INFO("allGather successfully, key: " << store_->GetCompleteKey(addKey) << ", rank: " << option_.rank <<
275	        ", size: " << size << ", timeCostUs: total(" << traceAllGather.PeriodUs() << ") append(" <<
276	        traceAppend.PeriodUs() << ") getStatus(" << traceGetStatus.PeriodUs() << ") getData(" <<
277	        traceGetData.PeriodUs() << ")");
278	
279	    return SM_OK;
280	}
281	
282	bool SmemNetGroupEngine::DealWithListenEvent(std::string& getVal, std::string& prevEvent)
283	{
284	    if (getVal.empty()) {
285	        return false;
286	    }
287	    char opt = getVal[0];
288	    if (!utils::NumUtil::IsDigit(getVal.substr(1))) {
289	        SHM_LOG_INFO("value is not digit");
290	        return false;
291	    }
292	
293	    long tmpValue = 0;
294	    if (!CharToLong(getVal.c_str() + 1, tmpValue)) {
295	        SHM_LOG_ERROR("convert string to long failed.");
296	        return false;
297	    }
298	    uint32_t rk = static_cast<uint32_t>(tmpValue);
299	    if (getVal == prevEvent) {
300	        return false;
301	    }
302	    prevEvent = getVal;
303	
304	    auto ret = store_->Get(SMEM_GROUP_DYNAMIC_SIZE_KEY, getVal, option_.timeoutMs);
305	    if (ret != SM_OK) {
306	        SHM_LOG_ERROR("get group dynamic size failed, ret: " << ret);
307	        return false;
308	    }
309	    if (!utils::NumUtil::IsDigit(getVal)) {
310	        SHM_LOG_INFO("value is not digit");
311	        return false;
312	    }
313	    tmpValue = 0;
314	    if (!StrToLong(getVal, tmpValue)) {
315	        SHM_LOG_ERROR("convert string to long failed.");
316	        return false;
317	    }
318	    int64_t tmpVal = static_cast<int64_t>(tmpValue);
319	    SHM_LOG_INFO("handle group event, local_rk:" << option_.rank << " event_rk:" << rk << " event:" << opt);
320	    UpdateGroupVersion(SplitSizeAndVersion(tmpVal).first + 1);
321	    if (opt == 'J') {
322	        option_.rankSize = static_cast<uint32_t>(SplitSizeAndVersion(tmpVal).second + 1);
323	        if (option_.joinCb != nullptr) {
324	            option_.joinCb(rk);
325	        }
326	    } else if (opt == 'L') {
327	        option_.rankSize = static_cast<uint32_t>(SplitSizeAndVersion(tmpVal).second - 1);
328	        if (option_.leaveCb != nullptr) {
329	            option_.leaveCb(rk);
330	        }
331	    } else {
332	        SHM_LOG_INFO("group listen event, unknown operation:" << opt);
333	    }
334	    return true;
335	}
336	
337	void SmemNetGroupEngine::GroupListenEvent()
338	{
339	    std::string getVal;
340	    std::string prevEvent;
341	
342	    listenThreadStarted_ = true;
343	    while (!groupStoped_) {
344	        if (!joined_) {
345	            usleep(SMEM_GROUP_SLEEP_TIMEOUT);
346	            continue;
347	        }
348	
349	        if (listenCtx_.watchId == UINT32_MAX) {
350	            uint32_t wid;
351	            auto ret = store_->Watch(SMEM_GROUP_LISTEN_EVENT_KEY, std::bind(&SmemNetGroupEngine::GroupWatchCb, this,
352	                std::placeholders::_1, std::placeholders::_2, std::placeholders::_3), wid);
353	            if (ret != SM_OK) {
354	                SHM_LOG_INFO("group watch failed, maybe link down, ret: " << ret);
355	                usleep(SMEM_GROUP_SLEEP_5S);
356	                continue;
357	            }
358	            listenCtx_.watchId = wid;
359	        }
360	
361	        auto ret = listenSignal_.TimedwaitMillsecs(SMEM_GROUP_LISTER_TIMEOUT);
362	        getVal = std::move(listenCtx_.value);
363	        if (groupStoped_) {
364	            break;
365	        }
366	
367	        listenCtx_.watchId = UINT32_MAX;
368	        if (ret != SM_OK || getVal.empty()) { // 非法watch事件,重新watch
369	            continue;
370	        }
371	
372	        if (!joined_) { // maybe has leaved
373	            continue;
374	        }
375	
376	        if (!DealWithListenEvent(getVal, prevEvent)) {
377	            continue;
378	        }
379	    }
380	    listenThreadStarted_ = false;
381	}
382	
383	void SmemNetGroupEngine::GroupWatchCb(int result, const std::string &key, const std::string &value)
384	{
385	    listenCtx_.ret = SM_OK;
386	    if (result != SM_OK) {
387	        SHM_LOG_ERROR("result: " << result);
388	        listenCtx_.ret = SM_ERROR;
389	    }
390	
391	    if (key != SMEM_GROUP_LISTEN_EVENT_KEY) {
392	        listenCtx_.ret = SM_ERROR;
393	    }
394	
395	    listenCtx_.value = value;
396	    listenSignal_.PthreadSignal();
397	}
398	
399	Result SmemNetGroupEngine::StartListenEvent()
400	{
401	    SHM_ASSERT_RETURN(listenSignal_.Initialize() == SM_OK, SM_ERROR);
402	
403	    std::thread th(&SmemNetGroupEngine::GroupListenEvent, this);
404	    while (!listenThreadStarted_) {
405	        usleep(SMEM_GROUP_SLEEP_TIMEOUT);
406	    }
407	    listenThread_ = std::move(th);
408	    return SM_OK;
409	}
410	
411	Result SmemNetGroupEngine::TryCasEventKey(std::string &val)
412	{
413	    uint64_t casTimes = 0;
414	    uint64_t casLimit = option_.timeoutMs / (SMEM_GROUP_SLEEP_TIMEOUT / SMEM_GROUP_MS_TO_US);
415	    std::string old;
416	    std::string prev = "";
417	    while (casTimes++ < casLimit) {
418	        auto ret = store_->Cas(SMEM_GROUP_LISTEN_EVENT_KEY, "", val, old);
419	        if (ret == SM_OK && old == val) {
420	            return SM_OK;
421	        }
422	        if (old != prev) {
423	            prev = old;
424	            casTimes = 0;
425	        }
426	        usleep(SMEM_GROUP_SLEEP_TIMEOUT);
427	    }
428	
429	    return SM_ERROR;
430	}
431	
432	Result SmemNetGroupEngine::GroupJoin()
433	{
434	    SHM_ASSERT_RETURN(option_.dynamic, SM_INVALID_PARAM);
435	    if (joined_) {
436	        return SM_OK;
437	    }
438	
439	    std::string val = "J" + std::to_string(option_.rank);
440	    if (TryCasEventKey(val) != SM_OK) {
441	        SHM_LOG_ERROR("cas event failed, maybe some rank fault!");
442	        return SM_ERROR;
443	    }
444	
445	    int64_t tmp;
446	    auto ret = store_->Add(SMEM_GROUP_DYNAMIC_SIZE_KEY, 0, tmp);
447	    if (ret != SM_OK) {
448	        SHM_LOG_ERROR("get group dynamic size failed, ret: " << ret);
449	        goto join_exit;
450	    }
451	
452	    GroupSnClean();
453	    UpdateGroupVersion(SplitSizeAndVersion(tmp).first + 1);
454	    option_.rankSize = static_cast<uint32_t>(SplitSizeAndVersion(tmp).second + 1);
455	    if (option_.joinCb != nullptr) {
456	        ret = option_.joinCb(option_.rank);
457	        if (ret != SM_OK) {
458	            SHM_LOG_ERROR("call join func failed, ret: " << ret);
459	            goto join_exit;
460	        }
461	    }
462	    ret = store_->Add(SMEM_GROUP_DYNAMIC_SIZE_KEY, 1LL << GROUP_DYNAMIC_SIZE_BIT_LEN | 1, tmp);
463	    if (ret != SM_OK) {
464	        SHM_LOG_ERROR("update group dynamic size failed, ret: " << ret);
465	    }
466	
467	join_exit:
468	    auto ret2 = store_->Remove(SMEM_GROUP_LISTEN_EVENT_KEY);
469	    if (ret2 != SM_OK) {
470	        SHM_LOG_ERROR("reset group event failed, ret: " << ret2);
471	    }
472	
473	    if (ret == SM_OK && ret2 == SM_OK) {
474	        joined_ = true;
475	        return SM_OK;
476	    }
477	    return SM_ERROR;
478	}
479	
480	Result SmemNetGroupEngine::GroupLeave()
481	{
482	    SHM_ASSERT_RETURN(option_.dynamic, SM_INVALID_PARAM);
483	    SHM_ASSERT_RETURN(joined_, SM_NOT_STARTED);
484	    Result ret = 0;
485	    std::string val = "L" + std::to_string(option_.rank);
486	    if (TryCasEventKey(val) != SM_OK) {
487	        SHM_LOG_ERROR("cas event failed, maybe some rank fault!");
488	        return SM_ERROR;
489	    }
490	
491	    if (option_.leaveCb != nullptr) {
492	        ret = option_.leaveCb(option_.rank);
493	        if (ret != SM_OK) {
494	            SHM_LOG_ERROR("call join func failed, ret: " << ret);
495	            goto leave_exit;
496	        }
497	    }
498	    int64_t tmpVal;
499	    ret = store_->Add(SMEM_GROUP_DYNAMIC_SIZE_KEY, GROUP_DYNAMIC_SIZE_BIT_MASK, tmpVal);
500	    if (ret != SM_OK) {
501	        SHM_LOG_ERROR("update group dynamic size failed, ret: " << ret);
502	    }
503	
504	    GroupSnClean();
505	    UpdateGroupVersion(SplitSizeAndVersion(tmpVal).first + 1);
506	
507	leave_exit:
508	    auto ret2 = store_->Remove(SMEM_GROUP_LISTEN_EVENT_KEY);
509	    if (ret2 != SM_OK) {
510	        SHM_LOG_ERROR("reset group event failed, ret: " << ret2);
511	    }
512	
513	    joined_ = false;
514	    if (ret == SM_OK && ret2 == SM_OK) {
515	        return SM_OK;
516	    }
517	    return SM_ERROR;
518	}
519	
520	void SmemNetGroupEngine::UpdateGroupVersion(int32_t ver)
521	{
522	    groupVersion_ = ver;
523	    allGatherGroupSn_ = 0;
524	    barrierGroupSn_ = 0;
525	}
526	
527	void SmemNetGroupEngine::GroupSnClean()
528	{
529	    for (uint32_t i = 0; i < REMOVE_INTERVAL; i++) {
530	        if (allGatherGroupSn_ < i) {
531	            break;
532	        }
533	        uint32_t rmAllGatherGroupSn_ = allGatherGroupSn_ - i;
534	        std::string removeAddIdx = std::to_string(groupVersion_) + "_" + std::to_string(rmAllGatherGroupSn_) + "_GA";
535	        std::string removeWaitIdx = std::to_string(groupVersion_) + "_" + std::to_string(rmAllGatherGroupSn_) + "_GW";
536	        (void)store_->Remove(removeAddIdx);
537	        (void)store_->Remove(removeWaitIdx);
538	    }
539	
540	    for (uint32_t i = 0; i < REMOVE_INTERVAL; i++) {
541	        if (barrierGroupSn_ < i) {
542	            break;
543	        }
544	        uint32_t removeBarrierGroupSn_ = barrierGroupSn_ - i;
545	        std::string removeAddIdx = std::to_string(groupVersion_) + "_" + std::to_string(removeBarrierGroupSn_) + "_BA";
546	        std::string removeWaitIdx = std::to_string(groupVersion_) + "_" + std::to_string(removeBarrierGroupSn_) + "_BW";
547	        (void)store_->Remove(removeAddIdx);
548	        (void)store_->Remove(removeWaitIdx);
549	    }
550	}
